"""Bind final browser, fidelity and performance evidence to the reviewed source."""
from pathlib import Path
import importlib.util,json
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'optimization/render-unification-v5'
spec=importlib.util.spec_from_file_location('coverage_gate',ROOT/'scripts/system/check_visual_coverage.py');gate=importlib.util.module_from_spec(spec);spec.loader.exec_module(gate)
inventory=json.loads((OUT/'site-inventory.json').read_text());matrix=json.loads((OUT/'after/site-checks.json').read_text())
additional=['home-interactions','library-interactions','intro-checks','master-alignment','resilience'];all_checks={}
for name in ['site-checks',*additional]:
    r=json.loads((OUT/'after'/f'{name}.json').read_text());assert r['results'] and all(row['passed'] for row in r['results']),name
    all_checks[name]={'passed':sum(bool(row['passed']) for row in r['results']),'total':len(r['results'])}
for name,sha in matrix['fingerprints'].items():assert gate.digest(ROOT/name)==sha,'Source changed since final browser review: '+name
proof={'version':6,'businessBase':inventory['businessBase'],'visualBase':inventory['baseCommit'],'entryDocuments':['index.html','explore.html'],'routes':inventory['routes'],'viewports':matrix['matrix']['viewports'],'screenshots':'optimization/render-unification-v5/after/page-audit.json','browserChecks':'optimization/render-unification-v5/after/site-checks.json','additionalBrowserChecks':[f'optimization/render-unification-v5/after/{name}.json' for name in additional],'performance':'optimization/render-unification-v5/after/performance-summary.json','contentFidelity':'optimization/render-unification-v5/after/content-fidelity.json','renderContract':{'actualPaint':True,'masterAlignment':'optimization/render-unification-v5/after/master-alignment.json','shortViewport':[1366,768],'imagesDecoded':True,'dataLayersPainted':True,'PlotlyHoverLayerClassified':True},'introReview':{'frames':'optimization/render-unification-v5/after/frame-performance.json','recording':'optimization/render-unification-v5/after/intro-demo-desktop.mp4','duration':5950,'runtimeMedia':False},'fingerprints':matrix['fingerprints']}
(ROOT/'app/visual-coverage.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n');gate.check()
performance=json.loads((OUT/'after/performance-summary.json').read_text());frames=json.loads((OUT/'after/frame-performance.json').read_text());fidelity=json.loads((OUT/'after/content-fidelity.json').read_text())
summary={'routeStates':len(inventory['routes']),'viewports':matrix['matrix']['viewports'],'screenshots':len(json.loads((OUT/'after/page-audit.json').read_text())['rows']),'checks':all_checks,'allPassed':True,'totalChecks':sum(v['total'] for v in all_checks.values()),'masterAlignmentChecks':65,'upstreamFiles':len(fidelity['files']),'upstreamVerifiedOrExact':sum(r['kind']!='documented presentation/integration exception' for r in fidelity['files']),'performance':performance['runs'],'introFrames':[{'profile':r['profile'],'elapsed':r['run']['elapsed'],'averageFPS':r['run']['averageFPS'],'p95Draw':r['run']['p95Draw'],'idleRAF':r['idleRAF'],'idlePixels':r['idlePixels']} for r in frames['runs']],'limitations':['Local Chromium plus viewport/DPR/CPU emulation; not real device or weak-network validation','Generated references are visual guidance only; original Master copy and scientific SVG geometry compared directly','Upstream research archives keep original LFS endpoint; production snapshot builds without those archives','Historical submission archive preserved, not part of current production navigation']}
(OUT/'after/validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'states':summary['routeStates'],'screenshots':summary['screenshots'],'checks':summary['totalChecks'],'allPassed':True}))
